Sounds good. Here's a first pass:

go
func CalculateRouteCost(legs []Leg, rates RateTable) (float64, error) {
	if len(legs) == 0 {
		return 0, ErrNoLegs
	}
	var total float64
	for i, l := range legs {
		if l.DistanceKm < 0 {
			return 0, fmt.Errorf("leg %d: negative distance", i)
		}
		rate, ok := rates.PerKm[l.Mode]
		if !ok {
			return 0, fmt.Errorf("leg %d: no rate for mode %q", i, l.Mode)
		}
		total += l.DistanceKm*rate + rates.FixedFee
	}
	return total, nil
}


One question: should a zero-distance leg still incur the fixed fee, or be free?

Got it. I'll add a NaN/Inf check and keep the fixed fee on zero-distance legs:

