Make `sha256` UNIQUE and upsert on it, so re-scanning a moved file just updates the path:

rust
const SCHEMA: &str = "
CREATE TABLE IF NOT EXISTS photos (
  id INTEGER PRIMARY KEY,
  sha256 TEXT NOT NULL UNIQUE,
  path TEXT NOT NULL,
  taken_at INTEGER,
  make TEXT, model TEXT,
  width INTEGER, height INTEGER,
  lat REAL, lon REAL
);
CREATE INDEX IF NOT EXISTS idx_photos_taken_at ON photos(taken_at);";

pub fn upsert(conn: &Connection, p: &PhotoMeta) -> rusqlite::Result<usize> {
    conn.prepare_cached(
        "INSERT INTO photos (sha256, path, taken_at, make, model, width, height, lat, lon)
         VALUES (?1,?2,?3,?4,?5,?6,?7,?8,?9)
         ON CONFLICT(sha256) DO UPDATE SET path = excluded.path"
    )?.execute(params![p.sha256, p.path, p.taken_at, p.make, p.model, p.width, p.height, p.lat, p.lon])
}

Use a half-open range so the index is used and boundaries don't double count:

rust
pub fn in_range(conn: &Connection, from: i64, to: i64) -> rusqlite::Result<Vec<PhotoMeta>> {
    let mut stmt = conn.prepare_cached(
        "SELECT sha256, path, taken_at, make, model, width, height, lat, lon
         FROM photos WHERE taken_at >= ?1 AND taken_at < ?2 ORDER BY taken_at"
    )?;
    let rows = stmt.query_map(params![from, to], |r| Ok(PhotoMeta {
        sha256: r.get(0)?, path: r.get(1)?, taken_at: r.get(2)?,
        make: r.get(3)?, model: r.get(4)?, width: r.get(5)?,
        height: r.get(6)?, lat: r.get(7)?, lon: r.get(8)?,
    }))?;
    rows.collect()
}

Almost certainly it's one implicit transaction per insert. Wrap the whole batch in a single transaction and turn on WAL:

rust
conn.pragma_update(None, "journal_mode", "WAL")?;
conn.pragma_update(None, "synchronous", "NORMAL")?;

let tx = conn.transaction()?;
for p in batch { upsert(&tx, p)?; }
tx.commit()?;


Because `upsert` uses `prepare_cached`, the statement is reused across the loop. That usually gives a big speedup.

